<?php session_start();require_once "db.php";if(!isset($_SESSION["uid"])){header("Location: login.php");exit;}$id=(int)($_GET["item_id"]??0);$s=$conn->prepare("SELECT m.*,r.name restaurant FROM menu_items m JOIN restaurants r ON m.restaurant_id=r.id WHERE m.id=?");$s->bind_param("i",$id);$s->execute();$item=$s->get_result()->fetch_assoc();$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$q=max(1,(int)$_POST["qty"]);$addr=trim($_POST["address"]);$total=$item["price"]*$q;$s=$conn->prepare("INSERT INTO orders(user_id,item_id,quantity,total,address) VALUES(?,?,?,?,?)");$s->bind_param("iiids",$_SESSION["uid"],$id,$q,$total,$addr);$msg=$s->execute()?"Order placed successfully!":"Order failed."; } ?>
<!doctype html><html><head><title>Order</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="container formbox"><h2>Order <?=htmlspecialchars($item["name"]??"")?></h2><p><?=htmlspecialchars($msg)?></p><form method="post"><input type="number" name="qty" value="1" min="1" required><textarea name="address" placeholder="Delivery address" required></textarea><button class="btn">Place Order</button></form><a href="menu.php?restaurant_id=<?=$item["restaurant_id"]??0?>">Back to menu</a></main></body></html>